    int n;
    cin >> n;
    vector<int> scores(n), order(n);
    for (int i = 0; i < n; ++i) {
        cin >> scores[i];
        order[i] = i;
    }
    sort(order.begin(), order.end(), [&](int a, int b) {
        if (scores[a] != scores[b]) {
            return scores[a] > scores[b];
        }
        return a < b;
    });
    int rank = 1;
    for (int i = 0; i < n; ++i) {
        if (i == 0 || scores[order[i]] != scores[order[i - 1]]) {
            rank = i + 1;
        }
        cout << order[i] + 1 << ' ' << rank << '\n';
    }
    return 0;
}

